using Godot;
using System.Linq;
using HakutaiKagami.Core.Contracts;
public partial class ContinuousWorldTrial
{
    MeshInstance3D? delegationLine;
    void BuildDelegationUI(HFlowContainer row){Add(row,"delegate-query","指定先へ照会",()=>{var c=S.DiagnosticSnapshot().Region!.Commands.LastOrDefault(c=>DelegationMission.Remote(S.DiagnosticSnapshot(),c.Request));if(c!=null)Require(S.QueryDelegation(new(new("request:delegate-query/"+S.Revision),c.Request.Id,true),S.PlayerControl,S.Revision));});buttons["delegate-query"].Visible=false;Add(row,"delegate-retry","不達命令を再送",()=>{var w=S.DiagnosticSnapshot();var c=RetryCandidate(w);if(c!=null){var unit=w.Region!.Units.First(u=>u.Commander==c.Request.Recipient);var address=RegionalBattle.View(w,S.PlayerControl).FirstOrDefault(v=>v.Unit==unit.Id)?.Position??w.Delegation!.Terms.KnownAddress;Require(S.RetryDelegation(c.Message,HakutaiKagami.Core.Messaging.MessageFlow.Latest(w.Messaging,c.Message).Id,S.PlayerControl,address,S.Revision));}});buttons["delegate-retry"].Visible=false;Add(row,"delegate-line","別働隊へ配置線を送る",()=>Require(S.IssueRegional(DelegationMission.Build(S.DiagnosticSnapshot(),"request:delegate-line/"+S.Revision,RegionalAction.Move),S.Revision)));Add(row,"delegate-return","別働隊へ帰還を送る",()=>Require(S.IssueRegional(DelegationMission.Build(S.DiagnosticSnapshot(),"request:delegate-return/"+S.Revision,RegionalAction.Retreat),S.Revision)));Add(row,"delegate-focus","指定線を見る",()=>{var w=S.DiagnosticSnapshot();var r=w.Region!.Commands.LastOrDefault(c=>DelegationMission.Remote(w,c.Request))?.Request??DelegationMission.Build(w,"request:focus-preview",RegionalAction.Move);center=r.Action==RegionalAction.Retreat?w.Delegation!.Terms.KnownAddress:new((r.A.X+r.B.X)/2,(r.A.Y+r.B.Y)/2);span=200;follow=false;});}
    RegionalCommand? RetryCandidate(ContractWorld w)=>w.Region!.Commands.LastOrDefault(c=>DelegationMission.Remote(w,c.Request)&&HakutaiKagami.Core.Messaging.MessageFlow.Latest(w.Messaging,c.Message) is {} a&&a.Number<3&&a.Status is HakutaiKagami.Core.Messaging.AttemptStatus.Lost or HakutaiKagami.Core.Messaging.AttemptStatus.Rejected&&HakutaiKagami.Core.Messaging.MessageFlow.FailureKnown(w.Messaging,a.Id,S.PlayerControl.Value));
    void RefreshDelegationUI(ContractWorld w){buttons["delegate-query"].Visible=w.Region!.Commands.Any(c=>DelegationMission.Remote(w,c.Request));buttons["delegate-retry"].Visible=RetryCandidate(w)!=null;var inbox=RegionalWork.Inbox(S);buttons["work-open"].Visible=inbox.Any(c=>c.CanOpen);buttons["work-accept"].Visible=buttons["work-decline"].Visible=inbox.Any(c=>c.CanDecide);buttons["retainer-interrupt"].Visible=KnownRetainerTask()!=null;buttons["retainer-explain"].Visible=OwnInterruptedTask()!=null;
        buttons["delegate-line"].Disabled=!DelegationMission.CanCommand(w,DelegationMission.Build(w,"request:preview-line",RegionalAction.Move),S.Seconds);buttons["delegate-return"].Disabled=!DelegationMission.CanCommand(w,DelegationMission.Build(w,"request:preview-return",RegionalAction.Retreat),S.Seconds);
        var row=DelegationMission.View(S,S.PlayerControl).LastOrDefault();string receipt=row?.Receipt=="applied"?"受令・着手の申告":row?.Receipt=="refused"?"拒否の申告":row?.Receipt=="unrecognized"?"命令未認識の返答":row==null?"まだ指示なし":Readable(row.Receipt);workRole.Text=w.Definitions.Characters.Single(c=>c.Id==S.PlayerControl).Name+" / 共同演習：他家軍の所有・主従はそのまま";workText.Text=(inbox.Length==0?"":MissionText(inbox.Last().Text)+"\n")+"別働隊："+receipt+" / "+(row?.Progress??"到達の返報は別に届きます")+" / 責任未審査";
        var query=DelegationInquiry.View(S,S.PlayerControl).LastOrDefault();if(query!=null)workText.Text+=" / "+query.State+(query.Progress==null?"":" / "+query.Progress+"（報告時刻"+query.ReportedAt+"秒）");
        delegationLine??=new MeshInstance3D{Mesh=new ImmediateMesh(),MaterialOverride=new StandardMaterial3D{AlbedoColor=new Color(.4f,.8f,1),ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded}};if(delegationLine.GetParent()==null)world.AddChild(delegationLine);var mesh=(ImmediateMesh)delegationLine.Mesh;mesh.ClearSurfaces();var command=w.Region!.Commands.LastOrDefault(c=>DelegationMission.Remote(w,c.Request));delegationLine.Visible=command?.Request.Action==RegionalAction.Move&&span<=30000;if(delegationLine.Visible){mesh.SurfaceBegin(Mesh.PrimitiveType.Lines);mesh.SurfaceAddVertex(P(command!.Request.A)+Vector3.Up*.4f);mesh.SurfaceAddVertex(P(command.Request.B)+Vector3.Up*.4f);mesh.SurfaceEnd();}
    }
}
